//! Tool list shown to MCP clients.

use serde_json::{json, Value};

fn obj(props: Value, required: &[&str]) -> Value {
    json!({ "type": "object", "properties": props, "required": required })
}

fn s(d: &str) -> Value {
    json!({ "type": "string", "description": d })
}

fn int(d: &str) -> Value {
    json!({ "type": "integer", "description": d })
}

fn flag(d: &str) -> Value {
    json!({ "type": "boolean", "description": d })
}

/// Properties every write tool accepts, merged into its own.
fn with_write(mut props: Value) -> Value {
    props["dry_run"] = flag("Return the unified diff and the diagnostics the change would produce; change nothing.");
    props["base_revision"] = s("Revision from get_project_state or list_files. The write is refused if the file it changes is different now.");
    props["change_report"] = json!({ "type": "string", "enum": ["summary", "full", "none"], "description": "Every write reply (a dry run too) carries change_report: a semantic before/after comparison, not a text diff. summary (default): exact counts in change_report.summary and at most 12 rows per list. full: up to 1000 rows per list. none: skip it (saves two parses and a build of every view on a large model)." });
    props
}

const SOURCE_ID: &str = "Optional id from the source project (for example an XMI id of another tool): 1 to 256 printable ASCII characters, no spaces. The server maps it to the element's qualified name in .sysml-bridge/ids.json inside the same write; rename and delete keep the map right and undo restores it. Look it up with resolve_source_id. An element may hold several ids; an id names one element. With if_absent on an element that exists, the id is attached to it and the reply says existed.";

/// What a tool writes: this is the one place a tool is classed, and the gate of `require_proposals` reads it from here.
/// `none`: a read. `model`: it writes model files (it is made with `write_tool`, which also gives it dry_run,
/// base_revision and change_report). `record`: it writes a record beside the model and never the model (a baseline, a
/// proposal).
fn classed(name: &str, description: &str, props: Value, required: &[&str], writes: &str) -> Value {
    json!({ "name": name, "description": description, "inputSchema": obj(props, required), "annotations": { "readOnlyHint": writes == "none" }, "_meta": { "writes": writes } })
}

fn tool(name: &str, description: &str, props: Value, required: &[&str]) -> Value {
    classed(name, description, props, required, "none")
}

fn write_tool(name: &str, description: &str, props: Value, required: &[&str]) -> Value {
    classed(name, description, with_write(props), required, "model")
}

fn record_tool(name: &str, description: &str, props: Value, required: &[&str]) -> Value {
    classed(name, description, props, required, "record")
}

/// What the tool list says `tool` writes: `model`, `record` or `none`. `None` for a name that is not a tool.
pub fn writes_of(tool: &str) -> Option<&'static str> {
    all_tools().as_array()?.iter().find(|t| t["name"] == tool)?["_meta"]["writes"].as_str()
}

/// Argument names a tool takes besides its declared properties.
const ALIASES: &[(&str, &[&str])] = &[("query_relationships", &["name"]), ("get_traceability", &["name"])];

/// Keys a nested `features[]` member takes.
const FEATURE_KEYS: &[&str] = &["kind", "name", "typed_by", "specializes", "redefines", "value", "short_name", "multiplicity", "direction", "doc", "modifiers", "source_id", "features"];
/// Keys of `add_interface` `names`.
const NAME_KEYS: &[&str] = &["port_def", "feature", "from_port", "to_port", "connection"];

fn unknown(key: &str, tool: &str, known: &[String]) -> String {
    format!("unknown argument {} for {}. Known: {}.", crate::agent::text::quote_clip(key), crate::edit::clip(tool), known.join(", "))
}

/// The tool list, built once: argument checks look tools up on every call and for every edit of a batch.
fn all_tools() -> &'static Value {
    static TOOLS: std::sync::OnceLock<Value> = std::sync::OnceLock::new();
    TOOLS.get_or_init(tools)
}

/// The argument names of `tool`: its schema properties and aliases. `None` for an unknown tool.
pub fn known_args(tool: &str) -> Option<Vec<String>> {
    let t = all_tools().as_array()?.iter().find(|t| t["name"] == tool)?;
    let mut keys: Vec<String> = t["inputSchema"]["properties"].as_object()?.keys().cloned().collect();
    for (n, extra) in ALIASES {
        if *n == tool {
            keys.extend(extra.iter().map(|s| s.to_string()));
        }
    }
    Some(keys)
}

/// Keys of an edit inside `apply_edits`: the schema of its op, without the per-call write options.
fn edit_keys(op: &str) -> Option<Vec<String>> {
    let tool = if crate::agent::intent::RAW_OPS.contains(&op) { "edit_model" } else { op };
    let mut keys = known_args(tool)?;
    keys.retain(|k| k != "dry_run" && k != "base_revision" && k != "change_report");
    keys.push("tool".into());
    if tool != "edit_model" {
        keys.push("op".into());
    }
    Some(keys)
}

fn check_nested(tool: &str, a: &Value) -> Result<(), String> {
    let features = |v: &Value, path: &str| -> Result<(), String> {
        let mut stack = vec![v];
        while let Some(x) = stack.pop() {
            for f in x.get("features").and_then(Value::as_array).into_iter().flatten() {
                let known: Vec<String> = FEATURE_KEYS.iter().map(|s| s.to_string()).collect();
                if let Some(k) = f.as_object().and_then(|o| o.keys().find(|k| !FEATURE_KEYS.contains(&k.as_str()))) {
                    return Err(unknown(k, path, &known));
                }
                stack.push(f);
            }
        }
        Ok(())
    };
    if tool == "create_element" {
        features(a, "create_element features[]")?;
    }
    if tool == "add_interface" {
        if let Some(k) = a.get("names").and_then(Value::as_object).and_then(|o| o.keys().find(|k| !NAME_KEYS.contains(&k.as_str()))) {
            return Err(unknown(k, "add_interface names", &NAME_KEYS.iter().map(|s| s.to_string()).collect::<Vec<_>>()));
        }
    }
    Ok(())
}

/// Refuse a call that names an argument the tool's schema does not declare.
pub fn check_args(tool: &str, a: &Value) -> Result<(), String> {
    let (Some(known), Some(obj)) = (known_args(tool), a.as_object()) else { return Ok(()) };
    if let Some(k) = obj.keys().find(|k| !known.contains(k)) {
        return Err(unknown(k, tool, &known));
    }
    check_nested(tool, a)?;
    if tool == "apply_edits" {
        // The count first: the checks below run once per edit, and the write layer would refuse the list only afterwards.
        let n = obj.get("edits").and_then(Value::as_array).map_or(0, Vec::len);
        if n > crate::agent::intent::MAX_EDITS {
            return Err(crate::agent::intent::too_many(n));
        }
        for (i, e) in obj.get("edits").and_then(Value::as_array).into_iter().flatten().enumerate() {
            let Some(eo) = e.as_object() else { continue };
            let op = eo.get("op").or_else(|| eo.get("tool")).and_then(Value::as_str).unwrap_or("");
            let Some(keys) = edit_keys(op) else { continue };
            if let Some(k) = eo.keys().find(|k| !keys.contains(k)) {
                return Err(format!("edit #{}: {}", i + 1, unknown(k, op, &keys)));
            }
            check_nested(op, e).map_err(|m| format!("edit #{}: {m}", i + 1))?;
        }
    }
    Ok(())
}

